effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec2 px = vec2(amount) / max(acScreenSize, vec2(1.0));
float a = radians(angle);
vec2 o = vec2(cos(a), sin(a)) * px;
float r = texture2DCv(inputImg.texture, clamp(uv - o, vec2(0.0), vec2(1.0))).r;
float g = texture2DCv(inputImg.texture, uv).g;
float b = texture2DCv(inputImg.texture, clamp(uv + o, vec2(0.0), vec2(1.0))).b;
vec4 src = texture2DCv(inputImg.texture, uv);
gl_FragColor = vec4(r, g, b, src.a);
}
